const quotes = [
  { text: '천 리 길도 한 걸음부터.', author: '속담' },
  { text: '오늘 걷지 않으면 내일은 뛰어야 한다.', author: '격언' },
  { text: '실패는 성공으로 가는 과정의 일부일 뿐이다.', author: '격언' },
  { text: '행복은 습관이다. 그것을 몸에 지니라.', author: '엘버트 허버드' },
  { text: '가장 큰 영광은 한 번도 실패하지 않음이 아니라, 실패할 때마다 다시 일어서는 데 있다.', author: '격언' },
  { text: '작은 기회로부터 종종 위대한 업적이 시작된다.', author: '데모스테네스' },
  { text: '배움에는 끝이 없다.', author: '격언' },
  { text: '지금 이 순간을 즐겨라.', author: '호라티우스' },
  { text: '꿈을 꿀 수 있다면, 이룰 수도 있다.', author: '격언' },
  { text: '어제보다 나은 오늘이면 충분하다.', author: '격언' }
];

const pick = quotes[Math.floor(Math.random() * quotes.length)];

return [{
  json: {
    quote: pick.text,
    author: pick.author,
    line: `"${pick.text}" - ${pick.author}`,
    generatedAt: new Date().toISOString()
  }
}];
